19		"time"
20	
21		internalblob "github.com/GopeedLab/gopeed/internal/blob"
22		"github.com/GopeedLab/gopeed/internal/controller"
23		"github.com/GopeedLab/gopeed/internal/fetcher"
24		"github.com/GopeedLab/gopeed/internal/logger"
25		"github.com/GopeedLab/gopeed/internal/tempfiles"
26		webviewproxy "github.com/GopeedLab/gopeed/internal/webview/proxy"
27		"github.com/GopeedLab/gopeed/pkg/base"
28		"github.com/GopeedLab/gopeed/pkg/protocol/ftp"
29		"github.com/GopeedLab/gopeed/pkg/protocol/http"
30		"github.com/GopeedLab/gopeed/pkg/util"
31		gonanoid "github.com/matoous/go-nanoid/v2"
32		"github.com/rs/zerolog"
33		"github.com/rs/zerolog/pkgerrors"
34	)
35	
36	const (
37		uploadCheckpointInterval = 30 * time.Second
38	
39		// task info bucket
40		bucketTask = "task"
41		// task download data bucket
42		bucketSave = "save"
43		// task statistics snapshot bucket
44		bucketTaskStats = "task_stats"
45		// protocol-level shared client state bucket
46		bucketProtocolState = "protocol_state"
47		bucketProtocolJobs  = "protocol_jobs"
48		// downloader config bucket
49		bucketConfig = "config"
50		// downloader extension bucket
51		bucketExtension = "extension"
52		// downloader extension storage bucket
53		bucketExtensionStorage = "extension_storage"
54	)
55	
56	var (
57		ErrTaskNotFound        = errors.New("task not found")
58		ErrUnSupportedProtocol = errors.New("unsupported protocol")
59	)
60	
61	type Listener func(event *Event)
62	
63	// ExtractStatus represents the current status of archive extraction
64	type ExtractStatus string
65	
66	const (
67		// ExtractStatusNone indicates extraction has not started
68		ExtractStatusNone ExtractStatus = ""
69		// ExtractStatusQueued indicates extraction is waiting in the queue
70		ExtractStatusQueued ExtractStatus = "queued"
71		// ExtractStatusWaitingParts indicates waiting for other multi-part archive parts to complete
72		ExtractStatusWaitingParts ExtractStatus = "waitingParts"
73		// ExtractStatusExtracting indicates extraction is in progress
74		ExtractStatusExtracting ExtractStatus = "extracting"
75		// ExtractStatusDone indicates extraction completed successfully
76		ExtractStatusDone ExtractStatus = "done"
77		// ExtractStatusError indicates extraction failed
78		ExtractStatusError ExtractStatus = "error"
79	)
80	
81	type Progress struct {
82		// Total download time(ns)
83		Used int64 `json:"used"`
84		// Download speed(bytes/s)
85		Speed int64 `json:"speed"`
86		// Downloaded size(bytes)
87		Downloaded int64 `json:"downloaded"`
88		// Uploaded speed(bytes/s)
89		UploadSpeed int64 `json:"uploadSpeed"`
90		// Uploaded size(bytes)
91		Uploaded int64 `json:"uploaded"`
92		// ExtractStatus indicates the current status of archive extraction
93		ExtractStatus ExtractStatus `json:"extractStatus"`
94		// ExtractProgress is the percentage of extraction completed (0-100)
95		ExtractProgress int `json:"extractProgress"`
96		// MultiPartBaseName is set for multi-part archives to group related parts
97		MultiPartBaseName string `json:"multiPartBaseName,omitempty"`
98		// MultiPartNumber is the part number for multi-part archives (1-indexed)
99		MultiPartNumber int `json:"multiPartNumber,omitempty"`
100		// MultiPartIsFirst indicates if this is the first part of a multi-part archive
101		MultiPartIsFirst bool `json:"multiPartIsFirst,omitempty"`
102	}
103	
104	type Downloader struct {
105		backgroundCtx       context.Context
106		cancelBackground    context.CancelFunc
107		protocolJobs        *protocolScheduler
108		tempFiles           *tempfiles.Scope
109		webviewProfilesLock sync.Mutex
110		webviewProfiles     map[string]*extensionWebViewProfile
111		webviewProxyLock    sync.Mutex
112		webviewProxy        *webviewproxy.Server
113		Logger              *logger.Logger
114		ExtensionLogger     *logger.Logger
115	
116		cfg          *DownloaderConfig
117		fetcherCache map[string]fetcher.Fetcher
118		storage      Storage
119		tasks        []*Task
120		waitTasks    []*Task
121		watchedTasks sync.Map
122		listener     Listener
123	
124		lock               *sync.Mutex
125		configLock         *sync.RWMutex
126		fetcherMapLock     *sync.RWMutex
127		checkDuplicateLock *sync.Mutex
128		closed             atomic.Bool
129	
130		// claimedExtractions tracks which multi-part archives have been claimed for extraction
131		// Key: fullBaseName (e.g., "/path/archive.7z"), Value: taskID that claimed it
132		claimedExtractions sync.Map
133	
134		extensions       []*Extension
135		extensionGitLock sync.Mutex
136		extensionGitWG   sync.WaitGroup
137		blob             *internalblob.Registry
138	}
139	
140	func NewDownloader(cfg *DownloaderConfig) *Downloader {
141		if cfg == nil {
142			cfg = &DownloaderConfig{}
143		}
144		cfg.Init()
145	
146		backgroundCtx, cancelBackground := context.WithCancel(context.Background())
147		d := &Downloader{
148			backgroundCtx:    backgroundCtx,
149			cancelBackground: cancelBackground,
150			cfg:              cfg,
151			fetcherCache:     make(map[string]fetcher.Fetcher),
152			waitTasks:        make([]*Task, 0),
153			storage:          cfg.Storage,
154	
155			lock:               &sync.Mutex{},
156			configLock:         &sync.RWMutex{},
157			fetcherMapLock:     &sync.RWMutex{},
158			checkDuplicateLock: &sync.Mutex{},
159	
160			extensions: make([]*Extension, 0),
161		}
162	
163		zerolog.ErrorStackMarshaler = pkgerrors.MarshalStack
164		d.Logger = logger.NewLogger(cfg.ProductionMode, filepath.Join(cfg.StorageDir, "logs", "core.log"))
165		d.ExtensionLogger = logger.NewLogger(cfg.ProductionMode, filepath.Join(cfg.StorageDir, "logs", "extension.log"))
166		if cfg.ProductionMode {
167			logPanic(filepath.Join(cfg.StorageDir, "logs"))
168		}
169		return d
170	}
171	
172	func (d *Downloader) Setup() error {
173		if err := d.setupTempDir(); err != nil {
174			return err
175		}
176		d.blob = internalblob.NewRegistry("")
177	
178		// setup storage
179		if err := d.storage.Setup([]string{bucketTask, bucketSave, bucketTaskStats, bucketProtocolState, bucketProtocolJobs, bucketConfig, bucketExtension, bucketExtensionStorage}); err != nil {
180			return err
181		}
182		// load config from storage
183		var cfg base.DownloaderStoreConfig
184		exist, err := d.storage.Get(bucketConfig, "config", &cfg)
185		if err != nil {
186			return err
187		}
188		if exist {
189			d.cfg.DownloaderStoreConfig = &cfg
190		} else {
191			d.cfg.DownloaderStoreConfig = &base.DownloaderStoreConfig{
192				FirstLoad: true,
193			}
194		}
195		// Move the legacy extra.downloadCategories list written by v2.0.0-beta
196		// builds into the top level categories field and persist the cleared key,
197		// before Init seeds the built-in categories. The config is written
198		// directly, PutConfig would validate a config that is not initialized yet.
199		if d.cfg.DownloaderStoreConfig.MigrateLegacyExtraCategories() {
200			if err := d.storage.Put(bucketConfig, "config", d.cfg.DownloaderStoreConfig); err != nil {
201				return err
202			}
203		}
204		// Initialize the current backend configuration schema and defaults.
205		if err := d.initProtocolConfigs(); err != nil {
206			return err
207		}
208		// Attach optional protocol state stores after configuration initialization.
209		for _, fm := range d.cfg.FetchManagers {
210			protocol := fm.Name()
211			if sfm, ok := fm.(fetcher.StatefulFetcherManager); ok {
212				sfm.SetStateStore(&protocolStateStore{
213					storage:  d.storage,
214					protocol: protocol,
215				})
216			}
217		}
218	
219		if err := d.setupProtocolJobs(); err != nil {
220			return err
221		}
222	
223		// load tasks from storage
224		var tasks []*Task
225		if err = d.storage.List(bucketTask, &tasks); err != nil {
226			return err
227		}
228		if tasks == nil {
229			tasks = make([]*Task, 0)
230		} else {
231			for i := len(tasks) - 1; i >= 0; i-- {
232				task := tasks[i]
233				// Remove broken tasks
234				if task.Meta == nil {
235					tasks = append(tasks[:i], tasks[i+1:]...)
236					continue
237				}
238				d.assignFetcherManager(task)
239				initTask(task)
240				if task.Status != base.DownloadStatusDone && task.Status != base.DownloadStatusError {
241					task.Status = base.DownloadStatusPause
242				}
243			}
244		}
245		d.tasks = tasks
246		// sort by create time
247		sort.Slice(d.tasks, func(i, j int) bool {
248			return d.tasks[i].CreatedAt.Before(d.tasks[j].CreatedAt)
249		})
250	
251		// load extensions from storage
252		var extensions []*Extension
253		if err = d.storage.List(bucketExtension, &extensions); err != nil {
254			return err
255		}
256		if extensions == nil {
257			extensions = make([]*Extension, 0)
258		}
259		d.extensions = extensions
260	
261		// Auto-cleanup non-existing tasks on startup
262		d.cleanupNonExistingTasks()
263	
264		// handle upload
265		go func() {
266			d.lock.Lock()
267			tasks := append([]*Task(nil), d.tasks...)
268			d.lock.Unlock()
269			for _, task := range tasks {
270				func() {
271					task.lock.Lock()
272					defer task.lock.Unlock()
273					if d.closed.Load() {
274						return
275					}
276					if d.taskStatus(task) != base.DownloadStatusDone || !task.Uploading {
277						return
278					}
279					if err := d.restoreTask(task); err != nil {
280						d.Logger.Error().Err(err).Msgf("task upload restore fetcher failed, task id: %s", task.ID)
281						return
282					}
283					if uploader, ok := task.fetcher.(fetcher.Uploader); ok {
284						if err := uploader.Upload(); err != nil {
285							d.Logger.Error().Err(err).Msgf("task upload failed, task id: %s", task.ID)
286						}
287					}
288				}()
289			}
290		}()
291	
292		// calculate download speed every tick
293		go func() {
294			lastUploadCheckpoint := time.Now()
295			for !d.closed.Load() {
296				uploadCheckpointDue := time.Since(lastUploadCheckpoint) >= uploadCheckpointInterval
297				d.lock.Lock()
298				tasks := append([]*Task(nil), d.tasks...)
299				d.lock.Unlock()
300				if len(tasks) > 0 {
301					for _, task := range tasks {
302						func() {
303							// Do not acquire d.lock (via GetTask) while holding
304							// statusLock; scheduling uses the opposite lock order.
305							if d.GetTask(task.ID) == nil {
306								return
307							}
308							// Startup can replace resource metadata while resolving a Blob.
309							// Skip that short transition instead of reading half-initialized state.
310							if !task.lock.TryLock() {
311								return
312							}
313							task.statusLock.Lock()
314							if task.Status != base.DownloadStatusRunning && !task.Uploading {
315								task.statusLock.Unlock()
316								task.lock.Unlock()
317								return
318							}
319							if task.fetcher == nil {
320								task.statusLock.Unlock()
321								task.lock.Unlock()
322								return
323							}
324	
325							current := task.fetcher.Progress().TotalDownloaded()
326							delta := current - task.Progress.Downloaded
327							if task.Meta != nil && task.Meta.Req != nil {
328								if producer := d.blob.Production(task.Meta.Req.URL); producer != nil {
329									downloaded, received := producer.Progress()
330									if task.producer != producer {
331										task.producer = producer
332										task.producerReceived = 0
333										task.speedArr = nil
334									}
335									current = downloaded
336									delta = max(0, received-task.producerReceived)
337									task.producerReceived = received
338								}
339							}
340							tick := float64(d.cfg.RefreshInterval) / 1000
341							downloadDataChanged := false
342							uploading := task.Uploading
343							if task.Status == base.DownloadStatusRunning {
344								downloadDataChanged = current != task.Progress.Downloaded
345								task.Progress.Used = task.timer.Used()
346								task.Progress.Speed = task.updateSpeed(max(0, delta), tick)
347								task.Progress.Downloaded = current
348							}
349	
350							uploadDataChanged := false
351							if uploading {
352								uploader := task.fetcher.(fetcher.Uploader)
353								currentUploaded := uploader.UploadedBytes()
354								uploadDataChanged = currentUploaded != task.Progress.Uploaded
355								task.Progress.UploadSpeed = task.updateUploadSpeed(currentUploaded-task.Progress.Uploaded, tick)
356								task.Progress.Uploaded = currentUploaded
357							}
358							task.statusLock.Unlock()
359							// Stats are pulled on the same cadence as speed so fetchers stay
360							// storage-agnostic. Runtime is refreshed in memory every tick, while
361							// only a changed durable Snapshot reaches bucketTaskStats.
362							if err := d.captureTaskStats(task, true, false); err != nil {
363								d.Logger.Warn().Err(err).Msgf("persist task stats failed, task id: %s", task.ID)
364							}
365							task.lock.Unlock()
366							// Listener callbacks may Pause/Continue and acquire statusLock.
367							d.emit(EventKeyProgress, task)
368	
369							// Store active upload state periodically even without traffic so
370							// protocol-owned values such as BT seed time remain durable.
371							if !shouldSaveTaskCheckpoint(
372								downloadDataChanged,
373								uploadDataChanged,
374								uploading,
375								uploadCheckpointDue,
376							) {
377								return
378							}
379							if err := d.saveTask(task); err != nil {
380								d.Logger.Warn().Err(err).Msgf("persist task checkpoint failed, task id: %s", task.ID)
381							}
382						}()
383					}
384				}
385				if uploadCheckpointDue {
386					lastUploadCheckpoint = time.Now()
387				}
388				time.Sleep(time.Millisecond * time.Duration(d.cfg.RefreshInterval))
389			}
390		}()
391		d.protocolJobs.start()
392		return nil
393	}
394	
395	func shouldSaveTaskCheckpoint(downloadChanged, uploadChanged, uploading, uploadCheckpointDue bool) bool {
396		return downloadChanged || uploadChanged || uploading && uploadCheckpointDue
397	}
