399	// cleanupNonExistingTasks checks for tasks whose files are missing on disk
400	// and removes them if the AutoCleanMissingFiles config is enabled.
401	func (d *Downloader) cleanupNonExistingTasks() {
402		cfg, err := d.GetConfig()
403		if err != nil {
404			return
405		}
406	
407		// If the feature is disabled, do nothing
408		if !cfg.AutoDeleteMissingFileTasks {
409			return
410		}
411	
412		var tasksToDelete []string
413	
414		for _, task := range d.tasks {
415			if task.Meta == nil || task.Meta.Res == nil {
416				continue
417			}
418	
419			var targetPath string
420			// Determine if it is a single file or a directory (multi-file torrent)
421			if task.Meta.Res.Name != "" {
422				targetPath = task.Meta.FolderPath()
423			} else {
424				targetPath = task.Meta.SingleFilepath()
425			}
426	
427			// Skip if path is empty
428			if targetPath == "" {
429				continue
430			}
431	
432			// Check if file/folder exists
433			if _, err := os.Stat(targetPath); os.IsNotExist(err) {
434				d.Logger.Info().Msgf("Auto-cleanup: task %s file not found at %s, removing from list", task.ID, targetPath)
435				tasksToDelete = append(tasksToDelete, task.ID)
436			}
437		}
438	
439		if len(tasksToDelete) > 0 {
440			d.Delete(&TaskFilter{IDs: tasksToDelete}, false)
441		}
442	}
