455	func (d *Downloader) setupFetcher(fm fetcher.FetcherManager, fetcher fetcher.Fetcher) {
456		ctl := controller.NewController()
457		ctl.TempDir = d.cfg.TempDir
458		ctl.TempFiles = d.tempFiles
459		ctl.ManagedProduction = func(raw string) bool { return d.blob.Production(raw) != nil }
460		ctl.GetConfig = func(v any) {
461			d.getProtocolConfig(fm.Name(), v)
462		}
463		if d.Logger != nil {
464			ctl.Logger = &d.Logger.Logger
465		}
466		// Get proxy config, task request proxy config has higher priority, then use global proxy config
467		ctl.GetProxy = func(requestProxy *base.RequestProxy) func(*gohttp.Request) (*url.URL, error) {
468			// Registry-backed blob URLs are loopback capability URLs and must never be
469			// sent through a configured proxy. Only exact, currently registered URLs
470			// take this path; everything else keeps normal HTTP proxy behavior.
471			if d.blob != nil && fetcher != nil && fetcher.Meta() != nil && fetcher.Meta().Req != nil && d.blob.IsURL(fetcher.Meta().Req.URL) {
472				return nil
473			}
474			if requestProxy == nil {
475				return d.cfg.Proxy.ToHandler()
476			}
477			switch requestProxy.Mode {
478			case base.RequestProxyModeNone:
479				return nil
480			case base.RequestProxyModeCustom:
481				return requestProxy.ToHandler()
482			default:
483				return d.cfg.Proxy.ToHandler()
484			}
485		}
486		fetcher.Setup(ctl)
487	}
