489	func (d *Downloader) saveTask(task *Task) error {
490		data, err := task.fetcherManager.Store(task.fetcher)
491		if err != nil {
492			d.Logger.Error().Stack().Err(err).Msgf("serialize fetcher failed: %s", task.ID)
493			return err
494		}
495		if data != nil {
496			if err := d.storage.Put(bucketSave, task.ID, data); err != nil {
497				d.Logger.Error().Stack().Err(err).Msgf("persist fetcher failed: %s", task.ID)
498				return err
499			}
500		} else {
501			if err := d.storage.Delete(bucketSave, task.ID); err != nil {
502				d.Logger.Error().Stack().Err(err).Msgf("clear fetcher state failed: %s", task.ID)
503				return err
504			}
505		}
506		task.statusLock.Lock()
507		snapshot := task.clone()
508		task.statusLock.Unlock()
509		if err := d.storage.Put(bucketTask, task.ID, snapshot); err != nil {
510			d.Logger.Error().Stack().Err(err).Msgf("persist task failed: %s", task.ID)
511			return err
512		}
513		return nil
514	}
