540	func (d *Downloader) Resolve(req *base.Request) (rr *ResolveResult, err error) {
541		rrId, err := gonanoid.New()
542		if err != nil {
543			return
544		}
545		ensureRequestRawURL(req)
546	
547		res, err := d.triggerOnResolve(req)
548		if err != nil {
549			return
550		}
551		if res != nil && len(res.Files) > 0 {
552			rr = &ResolveResult{
553				Res:                  res,
554				SuggestedDownloadDir: d.suggestedDownloadDir(res),
555			}
556			return
557		}
558	
559		fetcher, err := d.buildFetcher(req.URL)
560		if err != nil {
561			return
562		}
563		err = fetcher.Resolve(req)
564		if err != nil {
565			return
566		}
567		d.fetcherMapLock.Lock()
568		d.fetcherCache[rrId] = fetcher
569		d.fetcherMapLock.Unlock()
570		rr = &ResolveResult{
571			ID:                   rrId,
572			Res:                  fetcher.Meta().Res,
573			SuggestedDownloadDir: d.suggestedDownloadDir(fetcher.Meta().Res),
574		}
575		return
576	}
