595	func (d *Downloader) remainRunningCount() int {
596		runningCount := 0
597		for _, t := range d.tasks {
598			if d.taskStatus(t) == base.DownloadStatusRunning {
599				runningCount++
600			}
601		}
602		return d.cfg.MaxRunning - runningCount
603	}
