660	// CreateWithOptions creates a resolved task using the submitted options, or the
661	// default download options when opts is nil.
662	func (d *Downloader) CreateWithOptions(rrId string, opts *base.Options) (taskId string, err error) {
663		d.fetcherMapLock.RLock()
664		fetcher, ok := d.fetcherCache[rrId]
665		d.fetcherMapLock.RUnlock()
666		if !ok {
667			return "", errors.New("invalid resource id")
668		}
669		if opts == nil {
670			opts = &base.Options{}
671		}
672		// The options of the caller decide the global default download directory,
673		// the task options are prepared later, when the task starts.
674		defaultPath, err := d.prepareDefaultPath(opts)
675		if err != nil {
676			return "", err
677		}
678		taskOpts, err := d.initOptions(opts.Clone(), fetcher.Meta().Req.URL)
679		if err != nil {
680			return "", err
681		}
682		if res := fetcher.Meta().Res; res != nil {
683			for _, index := range taskOpts.SelectFiles {
684				if index < 0 || index >= len(res.Files) {
685					return "", fmt.Errorf("invalid selected file index: %d", index)
686				}
687			}
688			taskOpts.InitSelectFiles(len(res.Files))
689		}
690		fetcher.Meta().Opts = taskOpts
691		if res := fetcher.Meta().Res; res != nil {
692			res.CalcSize(fetcher.Meta().Opts.SelectFiles)
693		}
694		// Resolve has no creation options. Publish a submitted HTTP estimate now
695		// while preserving any size already confirmed by the response.
696		if taskOpts.Size > 0 {
697			if err := fetcher.Patch(nil, &base.Options{Size: taskOpts.Size}); err != nil {
698				return "", err
699			}
700		}
701		defer func() {
702			d.fetcherMapLock.Lock()
703			delete(d.fetcherCache, rrId)
704			d.fetcherMapLock.Unlock()
705		}()
706		taskId, err = d.doCreate(fetcher, nil)
707		if err == nil {
708			d.persistDefaultPathBestEffort(defaultPath)
709		}
710		return
711	}
712	
713	// Patch modifies task-specific data based on the protocol.
714	// For HTTP protocol, it can modify Request info.
715	// For BT protocol, it can modify SelectFiles.
716	func (d *Downloader) Patch(id string, req *base.Request, opts *base.Options) error {
717		task := d.GetTask(id)
718		if task == nil {
719			return ErrTaskNotFound
720		}
721		if err := func() error {
722			task.lock.Lock()
723			defer task.lock.Unlock()
724	
725			// Restore fetcher if not loaded
726			if task.fetcher == nil {
727				err := func() error {
728					task.statusLock.Lock()
729					defer task.statusLock.Unlock()
730	
731					return d.restoreFetcher(task)
732				}()
733				if err != nil {
734					return err
735				}
736			}
737	
738			// Call the fetcher's Patch method
739			if err := task.fetcher.Patch(req, httpSizeOptions(opts, task.Protocol)); err != nil {
740				return err
741			}
742	
743			// Update task meta from fetcher and transfer any live Blob lease.
744			task.Meta = task.fetcher.Meta()
745			if err := d.syncBlobTaskLease(task); err != nil {
746				return err
747			}
748	
749			return d.saveTask(task)
750		}(); err != nil {
751			return err
752		}
753	
754		// Emit outside task.lock so listeners may safely call back into Patch/Pause.
755		d.emit(EventKeyProgress, task)
756	
757		return nil
758	}
759	
760	func (d *Downloader) Pause(filter *TaskFilter) (err error) {
761		if filter == nil || filter.IsEmpty() {
762			return d.pauseAll()
763		}
764	
765		filter.NotStatuses = []base.Status{base.DownloadStatusPause, base.DownloadStatusError, base.DownloadStatusDone}
766		pauseTasks := d.GetTasksByFilter(filter)
767		if len(pauseTasks) == 0 {
768			return ErrTaskNotFound
769		}
770	
771		for _, task := range pauseTasks {
772			if err = d.doPause(task); err != nil {
773				return
774			}
775		}
776		d.notifyRunning()
777	
778		return
779	}
780	
781	func (d *Downloader) pauseAll() (err error) {
782		func() {
783			d.lock.Lock()
784			defer d.lock.Unlock()
785	
786			// Clear wait tasks
787			d.waitTasks = d.waitTasks[:0]
788		}()
789	
790		for _, task := range d.tasks {
791			if err = d.doPause(task); err != nil {
792				return
793			}
794		}
795	
796		return
797	}
798	
799	// Continue specific tasks, if continue tasks will exceed maxRunning, it needs pause some running tasks before that
800	func (d *Downloader) Continue(filter *TaskFilter) (err error) {
801		if filter == nil || filter.IsEmpty() {
802			return d.continueAll()
803		}
804	
805		filter.NotStatuses = []base.Status{base.DownloadStatusRunning, base.DownloadStatusDone}
806		continueTasks := d.GetTasksByFilter(filter)
807		if len(continueTasks) == 0 {
808			return ErrTaskNotFound
809		}
810	
811		realContinueTasks := make([]*Task, 0)
812		pausedTasks := make([]*Task, 0)
813		func() {
814			d.lock.Lock()
815			defer d.lock.Unlock()
816	
817			continueCount := len(continueTasks)
818			remainRunningCount := d.remainRunningCount()
819			needRunningCount := int(math.Min(float64(d.cfg.MaxRunning), float64(continueCount)))
820			needPauseCount := needRunningCount - remainRunningCount
821			if needPauseCount > 0 {
822				pausedCount := 0
823				for _, task := range d.tasks {
824					if task.Status == base.DownloadStatusRunning {
825						var queued bool
826						queued, err = d.doPauseForScheduling(task)
827						if err != nil {
828							return
829						}
830						if queued {
831							d.waitTasks = append(d.waitTasks, task)
832							pausedTasks = append(pausedTasks, task)
833							pausedCount++
834						}
835					}
836					if pausedCount == needPauseCount {
837						break
838					}
839				}
840			}
841	
842			for _, task := range continueTasks {
843				if len(realContinueTasks) < needRunningCount {
844					realContinueTasks = append(realContinueTasks, task)
845				} else {
846					task.Status = base.DownloadStatusWait
847					d.waitTasks = append(d.waitTasks, task)
848				}
849			}
850		}()
851		if err != nil {
852			return
853		}
854		// Scheduling pauses run while d.lock is held, but events must not: listeners
855		// are allowed to call back into Downloader methods that acquire d.lock.
856		for _, task := range pausedTasks {
857			d.emit(EventKeyPause, task)
858		}
859	
860		for _, task := range realContinueTasks {
861			if err = d.doStart(task); err != nil {
862				return
863			}
864		}
865	
866		return
867	}
868	
869	// continueAll continue all tasks but does not affect tasks already running
870	func (d *Downloader) continueAll() (err error) {
871		continuedTasks := make([]*Task, 0)
872	
873		func() {
874			d.lock.Lock()
875			defer d.lock.Unlock()
876			// calculate how many tasks can be continued, can't exceed maxRunning
877			remainCount := d.remainRunningCount()
878			for _, task := range d.tasks {
879				if task.Status != base.DownloadStatusRunning && task.Status != base.DownloadStatusDone {
880					if len(continuedTasks) < remainCount {
881						continuedTasks = append(continuedTasks, task)
882					} else {
883						task.Status = base.DownloadStatusWait
884						d.waitTasks = append(d.waitTasks, task)
885					}
886				}
887			}
888		}()
889	
890		for _, task := range continuedTasks {
891			if err = d.doStart(task); err != nil {
892				return
893			}
894		}
895	
896		return
897	}
898	
899	func (d *Downloader) ContinueBatch(filter *TaskFilter) (err error) {
900		if filter == nil || filter.IsEmpty() {
901			return d.continueAll()
902		}
903	
904		continueTasks := d.GetTasksByFilter(filter)
905		for _, task := range continueTasks {
906			if err = d.doStart(task); err != nil {
907				return
908			}
909		}
910		return
911	}
912	
913	// ContinueOnStartup applies the persisted startup policy after the backend is
914	// ready to accept connections. Continue(nil) intentionally preserves the same
915	// continue-all semantics exposed by the API, including retrying failed tasks.
916	func (d *Downloader) ContinueOnStartup() error {
917		if !d.cfg.DownloaderStoreConfig.AutoStartTasks {
918			return nil
919		}
920		return d.Continue(nil)
921	}
922	
923	func (d *Downloader) Delete(filter *TaskFilter, force bool) (err error) {
924		if filter == nil || filter.IsEmpty() {
925			return d.deleteAll(force)
926		}
927	
928		deleteTasks := d.GetTasksByFilter(filter)
929		if len(deleteTasks) == 0 {
930			return
931		}
932	
933		deleteIds := make([]string, 0)
934		deleteTasksPtr := make([]*Task, 0)
935		for _, task := range deleteTasks {
936			deleteIds = append(deleteIds, task.ID)
937			deleteTasksPtr = append(deleteTasksPtr, task)
938		}
939		func() {
940			d.lock.Lock()
941			defer d.lock.Unlock()
942	
943			for _, id := range deleteIds {
944				for i, t := range d.tasks {
945					if t.ID == id {
946						d.tasks = append(d.tasks[:i], d.tasks[i+1:]...)
947						break
948					}
949				}
950				for i, t := range d.waitTasks {
951					if t.ID == id {
952						d.waitTasks = append(d.waitTasks[:i], d.waitTasks[i+1:]...)
953						break
954					}
955				}
956			}
957		}()
958	
959		for _, task := range deleteTasksPtr {
960			err = d.doDelete(task, force)
961			if err != nil {
962				return
963			}
964		}
965	
966		d.notifyRunning()
967		return
968	}
