1332	// return tasks and if match all tasks
1333	func (d *Downloader) GetTasksByFilter(filter *TaskFilter) []*Task {
1334		d.lock.Lock()
1335		defer d.lock.Unlock()
1336	
1337		if filter == nil || filter.IsEmpty() {
1338			return d.tasks
1339		}
1340	
1341		idMatch := func(task *Task) bool {
1342			if len(filter.IDs) == 0 {
1343				return true
1344			}
1345			for _, id := range filter.IDs {
1346				if task.ID == id {
1347					return true
1348				}
1349			}
1350			return false
1351		}
1352		statusMatch := func(task *Task) bool {
1353			if len(filter.Statuses) == 0 {
1354				return true
1355			}
1356			for _, status := range filter.Statuses {
1357				if task.Status == status {
1358					return true
1359				}
1360			}
1361			return false
1362		}
1363		notStatusMatch := func(task *Task) bool {
1364			if len(filter.NotStatuses) == 0 {
1365				return true
1366			}
1367			for _, status := range filter.NotStatuses {
1368				if task.Status == status {
1369					return false
1370				}
1371			}
1372			return true
1373		}
1374	
1375		tasks := make([]*Task, 0)
1376		for _, task := range d.tasks {
1377			if idMatch(task) && statusMatch(task) && notStatusMatch(task) {
1378				tasks = append(tasks, task)
1379			}
1380		}
1381		return tasks
1382	}
