1399	func (d *Downloader) PutConfig(v *base.DownloaderStoreConfig) error {
1400		if v == nil {
1401			return errors.New("config is nil")
1402		}
1403		next := util.DeepClone(v)
1404		changedProtocols := []string{}
1405		d.configLock.Lock()
1406		if d.closed.Load() {
1407			d.configLock.Unlock()
1408			return errors.New("downloader is closed")
1409		}
1410		if next.GithubMirror == nil {
1411			next.GithubMirror = util.DeepClone(d.cfg.GithubMirror)
1412		}
1413		if err := next.GithubMirror.Validate(); err != nil {
1414			d.configLock.Unlock()
1415			return err
1416		}
1417		if next.ProtocolConfig == nil {
1418			next.ProtocolConfig = map[string]any{}
1419		}
1420		for name := range next.ProtocolConfig {
1421			if _, err := d.protocolManager(name); err != nil {
1422				d.configLock.Unlock()
1423				return err
1424			}
1425		}
1426		for _, fm := range d.cfg.FetchManagers {
1427			name := fm.Name()
1428			value, exists := next.ProtocolConfig[name]
1429			if !exists {
1430				value = d.cfg.ProtocolConfig[name]
1431			}
1432			value, err := preserveProtocolState(value, d.cfg.ProtocolConfig[name])
1433			if err == nil {
1434				value, err = normalizeProtocol(fm, value)
1435			}
1436			if err != nil {
1437				d.configLock.Unlock()
1438				return err
1439			}
1440			next.ProtocolConfig[name] = value
1441			oldJSON, _ := json.Marshal(d.cfg.ProtocolConfig[name])
1442			newJSON, _ := json.Marshal(value)
1443			if !bytes.Equal(oldJSON, newJSON) {
1444				changedProtocols = append(changedProtocols, name)
1445			}
1446		}
1447		if err := d.storage.Put(bucketConfig, "config", next); err != nil {
1448			d.configLock.Unlock()
1449			return err
1450		}
1451		d.cfg.DownloaderStoreConfig = next
1452		d.configLock.Unlock()
1453		if d.protocolJobs != nil {
1454			for _, name := range changedProtocols {
1455				d.protocolJobs.changed(name)
1456			}
1457		}
1458		return nil
1459	}
