1661	// postDownloadExtra returns the auto-torrent and auto-extract options of a
1662	// finished single-file task, in the HTTP options shape the extraction code
1663	// takes. FTP options carry the same fields. An FTP folder has no single file
1664	// to act on, so it gets nil, as does any other protocol.
1665	func postDownloadExtra(meta *fetcher.FetcherMeta) *http.OptsExtra {
1666		if meta == nil || meta.Opts == nil {
1667			return nil
1668		}
1669		switch e := meta.Opts.Extra.(type) {
1670		case *http.OptsExtra:
1671			return e
1672		case *ftp.OptsExtra:
1673			if meta.Res == nil || meta.Res.Name != "" || len(meta.Res.Files) != 1 {
1674				return nil
1675			}
1676			return &http.OptsExtra{
1677				Connections:                e.Connections,
1678				AutoTorrent:                e.AutoTorrent,
1679				DeleteTorrentAfterDownload: e.DeleteTorrentAfterDownload,
1680				AutoExtract:                e.AutoExtract,
1681				ArchivePassword:            e.ArchivePassword,
1682				DeleteAfterExtract:         e.DeleteAfterExtract,
1683			}
1684		}
1685		return nil
1686	}
