1696	func (d *Downloader) handleOnError(task *Task, err error, resetFetcher bool) {
1697		if task == nil || task.lock == nil {
1698			return
1699		}
1700		task.lock.Lock()
1701		if !d.markTaskError(task) {
1702			task.lock.Unlock()
1703			return
1704		}
1705		d.Logger.Warn().Err(err).Msgf("task download failed, task id: %s", task.ID)
1706		oldURL := ""
1707		if task.Meta != nil && task.Meta.Req != nil {
1708			oldURL = task.Meta.Req.URL
1709		}
1710		d.triggerOnError(task, err)
1711		newURL := ""
1712		if task.Meta != nil && task.Meta.Req != nil {
1713			newURL = task.Meta.Req.URL
1714		}
1715		if oldURL != "" && newURL != oldURL {
1716			// Extensions are allowed to replace an expired URL from onError. Patch the
1717			// existing fetcher through its public API so protocol-owned redirect state
1718			// is reset without teaching the HTTP fetcher about blob URLs.
1719			if task.fetcher != nil {
1720				if patchErr := task.fetcher.Patch(&base.Request{URL: newURL}, nil); patchErr != nil {
1721					d.Logger.Warn().Err(patchErr).Msgf("patch recovered task url failed, task id: %s", task.ID)
1722				}
1723			}
1724			d.releaseBlobTaskURL(task, oldURL)
1725		}
1726		if resetFetcher && d.taskStatus(task) == base.DownloadStatusRunning {
1727			if resetErr := d.resetTaskFetcher(task); resetErr != nil {
1728				d.Logger.Warn().Err(resetErr).Msgf("reset recovered task fetcher failed, task id: %s", task.ID)
1729			}
1730		}
1731		if statsErr := d.captureTaskStats(task, false, true); statsErr != nil {
1732			d.Logger.Warn().Err(statsErr).Msgf("persist failed task stats failed, task id: %s", task.ID)
1733		}
1734		if d.taskStatus(task) == base.DownloadStatusError {
1735			if persistErr := d.storage.Put(bucketTask, task.ID, task.clone()); persistErr != nil {
1736				d.Logger.Error().Stack().Err(persistErr).Msgf("persist failed task failed, task id: %s", task.ID)
1737			}
1738		}
1739		task.lock.Unlock()
1740		if d.taskStatus(task) == base.DownloadStatusError {
1741			d.releaseBlobTask(task)
1742			d.emit(EventKeyError, task, err)
1743			d.emit(EventKeyFinally, task, err)
1744			d.notifyRunning()
1745			d.triggerWebhooks(WebhookEventDownloadError, task, err)
1746		}
1747	}
