1749	func (d *Downloader) resetTaskFetcher(task *Task) error {
1750		if task == nil || task.Meta == nil || task.Meta.Req == nil {
1751			return errors.New("task request is unavailable")
1752		}
1753		fm, err := d.parseFm(task.Meta.Req.URL)
1754		if err != nil {
1755			return err
1756		}
1757		opts := task.Meta.Opts
1758		f := fm.Build()
1759		d.setupFetcher(fm, f)
1760		// A fresh source must never inherit bytes or preallocation from the failed
1761		// source. HTTP opens existing targets without truncating them, so remove the
1762		// old single-file target before installing a fresh fetcher.
1763		if task.Meta.Res != nil && task.Meta.Opts != nil && len(task.Meta.Res.Files) > 0 {
1764			if err := util.SafeRemove(task.Meta.SingleFilepath()); err != nil {
1765				return err
1766			}
1767		}
1768		f.Meta().Req = task.Meta.Req
1769		f.Meta().Opts = opts
1770		task.fetcherManager = fm
1771		task.fetcher = f
1772		task.Meta = f.Meta()
1773		if task.Progress != nil {
1774			task.Progress.Downloaded = 0
1775			task.Progress.Speed = 0
1776		}
1777		task.statsLock.Lock()
1778		task.statsLoaded = true
1779		task.stats = nil
1780		task.statsSnapshot = nil
1781		task.statsLock.Unlock()
1782		if err := d.storage.Delete(bucketTaskStats, task.ID); err != nil {
1783			return err
1784		}
1785		return d.storage.Delete(bucketSave, task.ID)
1786	}
