1822	func (d *Downloader) doCreate(f fetcher.Fetcher, opts *base.Options) (taskId string, err error) {
1823		if f.Meta().Opts == nil {
1824			f.Meta().Opts = opts
1825		}
1826		ensureRequestRawURL(f.Meta().Req)
1827	
1828		fm, err := d.parseFm(f.Meta().Req.URL)
1829		if err != nil {
1830			return
1831		}
1832		task := NewTask()
1833		task.fetcherManager = fm
1834		task.fetcher = f
1835		task.Protocol = fm.Name()
1836		task.Meta = f.Meta()
1837		task.Progress = &Progress{}
1838		_, task.Uploading = f.(fetcher.Uploader)
1839		// A new task still needs its first preparation, it decides the download
1840		// directory and the final name of the task.
1841		task.NeedsPreparation = true
1842		initTask(task)
1843		if err = d.syncBlobTaskLease(task); err != nil {
1844			return "", err
1845		}
1846		defer func() {
1847			if err != nil {
1848				d.releaseBlobTask(task)
1849			}
1850		}()
1851		if err = d.storage.Put(bucketTask, task.ID, task.clone()); err != nil {
1852			return
1853		}
1854		taskId = task.ID
1855	
1856		func() {
1857			d.lock.Lock()
1858			defer d.lock.Unlock()
1859	
1860			d.tasks = append(d.tasks, task)
1861	
1862			remainRunningCount := d.remainRunningCount()
1863			if remainRunningCount == 0 {
1864				task.Status = base.DownloadStatusWait
1865				d.waitTasks = append(d.waitTasks, task)
1866				return
1867			}
1868	
1869			err = d.doStart(task)
1870		}()
1871	
1872		return
1873	}
