1875	// httpSizeOptions keeps estimates out of other protocols, including HLS URLs
1876	// served over HTTP. Clone before filtering because batch tasks may share options.
1877	func httpSizeOptions(opts *base.Options, protocol string) *base.Options {
1878		if opts != nil && opts.Size != 0 && (protocol != "http" || opts.Size < 0) {
1879			opts = opts.Clone()
1880			opts.Size = 0
1881		}
1882		return opts
