1885	// initOptions makes sure the option set is usable: a nil option set becomes
1886	// an empty one, the selection is never nil and the base download directory
1887	// falls back to the configured one. The directory is decided and checked
1888	// against the white list when the task starts.
1889	func (d *Downloader) initOptions(opts *base.Options, requestURL string) (*base.Options, error) {
1890		if opts == nil {
1891			opts = &base.Options{}
1892		}
1893		if opts.Size != 0 {
1894			fm, err := d.parseFm(requestURL)
1895			if err != nil {
1896				return nil, err
1897			}
1898			opts = httpSizeOptions(opts, fm.Name())
1899		}
1900		if opts.SelectFiles == nil {
1901			opts.SelectFiles = make([]int, 0)
1902		}
1903		if opts.Path == "" {
1904			cfg, err := d.GetConfig()
1905			if err != nil {
1906				return nil, err
1907			}
1908			opts.Path = cfg.DownloadDir
1909		}
1910		return opts, nil
1911	}
