1913	func (d *Downloader) initDownloadPath(path string) (string, error) {
1914		// Replace placeholders in download path (e.g., %year%, %month%, %day%, %date%)
1915		path = util.ReplacePathPlaceholders(path)
1916	
1917		// if enable white download directory, check if the download directory is in the white list
1918		if len(d.cfg.WhiteDownloadDirs) > 0 {
1919			inWhiteList := false
1920			for _, dir := range d.cfg.WhiteDownloadDirs {
1921				if match, err := filepath.Match(dir, path); match && err == nil {
1922					inWhiteList = true
1923					break
1924				}
1925			}
1926			if !inWhiteList {
1927				return "", errors.New("download directory is not in white list")
1928			}
1929		}
1930		return path, nil
1931	}
