2001	func (d *Downloader) doStart(task *Task) (err error) {
2002		var generation uint64
2003		isReturn, err := d.statusMut(task, func() (isReturn bool, err error) {
2004			if task.Status == base.DownloadStatusRunning || task.Status == base.DownloadStatusDone {
2005				isReturn = true
2006				return
2007			}
2008	
2009			err = d.restoreTask(task)
2010			if err != nil {
2011				d.Logger.Error().Stack().Err(err).Msgf("restore fetcher failed, task id: %s", task.ID)
2012				return
2013			}
2014			task.updateStatus(base.DownloadStatusRunning)
2015			task.runGeneration++
2016			generation = task.runGeneration
2017	
2018			return
2019		})
2020		if err != nil {
2021			d.Logger.Error().Stack().Err(err).Msgf("start task failed, task id: %s", task.ID)
2022			return
2023		}
2024		if isReturn {
2025			return
2026		}
2027	
2028		started := false
2029		handler := func() error {
2030			task.lock.Lock()
2031			defer task.lock.Unlock()
2032			if !d.taskIsRunningGeneration(task, generation) {
2033				return nil
2034			}
2035	
2036			if task.fetcher == nil {
2037				if err := d.restoreFetcher(task); err != nil {
2038					return err
2039				}
2040			}
2041			d.triggerOnStart(task)
2042			if !d.taskIsRunningGeneration(task, generation) {
2043				return nil
2044			}
2045			if task.fetcher != nil {
2046				task.fetcher.Meta().Req = task.Meta.Req
2047				task.fetcher.Meta().Res = task.Meta.Res
2048				task.fetcher.Meta().Opts = task.Meta.Opts
2049			}
2050			if err := d.syncBlobTaskLease(task); err != nil {
2051				return err
2052			}
2053			resolvedHere := task.Meta.Res == nil
2054			if resolvedHere {
2055				err := task.fetcher.Resolve(task.Meta.Req)
2056				if err != nil {
2057					return err
2058				}
2059				task.Meta.Res = task.fetcher.Meta().Res
2060			}
2061	
2062			if task.NeedsPreparation {
2063				if task.fetcherManager.AutoRename() {
2064					// The duplicate name is resolved from the files on disk, but
2065					// the file only appears when the fetcher starts, so the lock
2066					// has to cover the start as well.
2067					d.checkDuplicateLock.Lock()
2068					defer d.checkDuplicateLock.Unlock()
2069				}
2070				// The first preparation decides the download directory and the
2071				// final name of the task. It runs for every task that has not
2072				// been prepared yet, no matter whether the task waited in the
2073				// queue, was paused or failed before.
2074				if err := d.prepareTask(task); err != nil {
2075					return err
2076				}
2077			} else if _, err := d.initDownloadPath(task.Meta.Opts.Path); err != nil {
2078				// A prepared task keeps its directory, but the directory still has
2079				// to pass the white list on every start.
2080				return err
2081			}
2082	
2083			task.statusLock.Lock()
2084			task.Progress.Speed = 0
2085			task.statusLock.Unlock()
2086			if !d.taskIsRunningGeneration(task, generation) {
2087				return nil
2088			}
2089			task.timer.Start()
2090			if err := task.fetcher.Start(); err != nil {
2091				return err
2092			}
2093			started = true
2094			if err := d.captureTaskStats(task, true, true); err != nil {
2095				// Statistics are auxiliary. A storage or serialization failure must not
2096				// turn an already-started download into a failed task.
2097				d.Logger.Warn().Err(err).Msgf("persist started task stats failed, task id: %s", task.ID)
2098			}
2099			if err := d.saveTask(task); err != nil {
2100				return err
2101			}
2102			return nil
2103		}
2104		go func() {
2105			if err := handler(); err != nil {
2106				if d.taskIsRunningGeneration(task, generation) {
2107					d.doOnError(task, err)
2108				}
2109				return
2110			}
2111			if started {
2112				if d.taskIsRunningGeneration(task, generation) {
2113					d.emit(EventKeyStart, task)
2114				}
2115				go d.watch(task)
2116			}
2117		}()
2118	
2119		return
2120	}
2121	
2122	func (d *Downloader) doPause(task *Task) (err error) {
2123		generation, isReturn, err := d.preparePause(task)
2124		if err != nil || isReturn {
2125			return err
2126		}
2127		handled, err := d.runPauseHandler(task, generation, true)
2128		if err != nil {
2129			d.Logger.Error().Stack().Err(err).Msgf("pause task handle failed, task id: %s", task.ID)
2130			return err
2131		}
2132		if handled {
2133			d.emit(EventKeyPause, task)
2134			d.triggerWebhooks(WebhookEventDownloadPause, task, nil)
2135		}
2136		return nil
2137	}
2138	
2139	// doPauseForScheduling physically pauses a running task without emitting while
2140	// the caller holds d.lock, then atomically moves it to the wait queue state.
2141	func (d *Downloader) doPauseForScheduling(task *Task) (bool, error) {
2142		generation, isReturn, err := d.preparePause(task)
2143		if err != nil || isReturn {
2144			return false, err
2145		}
2146		handled, err := d.runPauseHandler(task, generation, true)
2147		if err != nil || !handled {
2148			return false, err
2149		}
2150		task.statusLock.Lock()
2151		queued := task.Status == base.DownloadStatusPause && task.runGeneration == generation
2152		if queued {
2153			task.Status = base.DownloadStatusWait
2154		}
2155		task.statusLock.Unlock()
2156		return queued, nil
2157	}
2158	
2159	func (d *Downloader) preparePause(task *Task) (generation uint64, isReturn bool, err error) {
2160		isReturn, err = d.statusMut(task, func() (isReturn bool, err error) {
2161			if task.Status == base.DownloadStatusPause || task.Status == base.DownloadStatusDone || task.Status == base.DownloadStatusError {
2162				isReturn = true
2163				return
2164			}
2165	
2166			task.updateStatus(base.DownloadStatusPause)
2167			task.runGeneration++
2168			generation = task.runGeneration
2169			task.timer.Pause()
2170			return
2171		})
2172		if err != nil {
2173			d.Logger.Error().Stack().Err(err).Msgf("pause task failed, task id: %s", task.ID)
2174		}
2175		return generation, isReturn, err
2176	}
2177	
2178	func (d *Downloader) runPauseHandler(task *Task, generation uint64, pauseFetcher bool) (bool, error) {
2179		task.lock.Lock()
2180		defer task.lock.Unlock()
2181		if !d.taskIsPausedGeneration(task, generation) {
2182			return false, nil
2183		}
2184	
2185		if pauseFetcher && task.fetcher != nil {
2186			if err := task.fetcher.Pause(); err != nil {
2187				return false, err
2188			}
2189		}
2190		if task.fetcher != nil {
2191			if err := d.captureTaskStats(task, false, true); err != nil {
2192				// The fetcher is already paused at this point. Keep the task lifecycle
2193				// successful even if its optional statistics snapshot cannot be stored.
2194				d.Logger.Warn().Err(err).Msgf("persist paused task stats failed, task id: %s", task.ID)
2195			}
2196		}
2197		if task.fetcherManager != nil && task.fetcher != nil {
2198			if err := d.saveTask(task); err != nil {
2199				return false, err
2200			}
2201		} else {
2202			if err := d.storage.Put(bucketTask, task.ID, task.clone()); err != nil {
2203				return false, err
2204			}
2205		}
2206		return true, nil
2207	}
