2326	// enqueueSingleExtraction queues extraction for a single (non-multi-part) archive
2327	func (d *Downloader) enqueueSingleExtraction(task *Task, downloadFilePath string, opts *http.OptsExtra) {
2328		jobID := "single:" + task.ID
2329	
2330		// Set extraction status to queued
2331		task.Progress.ExtractStatus = ExtractStatusQueued
2332		d.emit(EventKeyProgress, task)
2333		d.storage.Put(bucketTask, task.ID, task.clone())
2334		d.Logger.Info().Msgf("extraction queued, task id: %s, job id: %s", task.ID, jobID)
2335	
2336		// Create and enqueue the extraction job
2337		job := NewExtractionJob(jobID, func() {
2338			d.performExtraction(task, downloadFilePath, task.Meta.Opts.Path, opts)
2339		})
2340	
2341		go func() {
2342			GetExtractionQueue().Enqueue(job)
2343		}()
2344	}
