2400	// checkMultiPartArchiveReady checks if all parts of a multi-part archive are downloaded
2401	// by examining task status rather than file existence
2402	func (d *Downloader) checkMultiPartArchiveReady(filePath string, destDir string, partInfo ArchivePartInfo) (bool, []string) {
2403		// Use task-based checking - find all tasks with the same MultiPartBaseName
2404		// and verify they are all in Done status
2405		baseName := GetMultiPartArchiveBaseName(filePath)
