2715	func (d *Downloader) syncBlobTaskLease(task *Task) error {
2716		if d.blob == nil || task == nil || task.Meta == nil || task.Meta.Req == nil {
2717			return nil
2718		}
2719		if task.blobRefLock == nil {
2720			task.blobRefLock = &sync.Mutex{}
2721		}
2722		task.blobRefLock.Lock()
2723		defer task.blobRefLock.Unlock()
2724		terminal := false
2725		if task.statusLock != nil {
2726			task.statusLock.Lock()
2727			terminal = task.Status == base.DownloadStatusDone || task.Status == base.DownloadStatusError
2728			task.statusLock.Unlock()
2729		}
2730		newURL := ""
2731		if !terminal && d.blob.IsURL(task.Meta.Req.URL) {
2732			newURL = task.Meta.Req.URL
2733		}
2734		if task.blobURL == newURL {
2735			return nil
2736		}
2737		if newURL != "" {
2738			if err := d.blob.Acquire(newURL); err != nil {
2739				return err
2740			}
2741		}
2742		oldURL := task.blobURL
2743		task.blobURL = newURL
2744		if oldURL != "" {
2745			_ = d.blob.Release(oldURL)
2746		}
2747		return nil
2748	}
