75				key := name + "/" + spec.Name
76				if _, ok := scheduler.jobs[key]; ok {
77					return fmt.Errorf("duplicate protocol job: %s", key)
78				}
79				entry := &registeredJob{protocol: name, spec: spec, wake: make(chan struct{}, 1)}
80				if _, err := d.storage.Get(bucketProtocolJobs, key, &entry.state); err != nil {
81					return err
82				}
83				scheduler.jobs[key] = entry
84			}
85		}
86		d.protocolJobs = scheduler
87		return nil
88	}
89	func (s *protocolScheduler) start() {
90		for key, entry := range s.jobs {
91			s.wg.Add(1)
92			go s.loop(key, entry)
93		}
94	}
95	func (s *protocolScheduler) signal(entry *registeredJob) {
96		select {
97		case entry.wake <- struct{}{}:
98		default:
99		}
100	}
101	func (s *protocolScheduler) changed(protocol string) {
102		for _, entry := range s.jobs {
103			if protocol == "" || entry.protocol == protocol {
104				entry.force.Store(true)
105				s.signal(entry)
106			}
107		}
108	}
109	func (s *protocolScheduler) loop(key string, entry *registeredJob) {
110		defer s.wg.Done()
111		entry.mu.Lock()
112		if entry.next.IsZero() {
113			entry.next = entry.state.LastSuccess.Add(entry.spec.Every)
114			if entry.next.Before(time.Now()) {
115				entry.next = time.Now().Add(time.Second)
116			}
117		}
118		next := entry.next
119		entry.mu.Unlock()
120		timer := time.NewTimer(time.Until(next))

