3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"reflect"
8		"strings"
9	
10		"github.com/GopeedLab/gopeed/internal/fetcher"
11		"github.com/GopeedLab/gopeed/pkg/util"
12	)
13	
14	func (d *Downloader) protocolManager(name string) (fetcher.FetcherManager, error) {
15		for _, fm := range d.cfg.FetchManagers {
16			if fm.Name() == name {
17				return fm, nil
18			}
19		}
20		return nil, fmt.Errorf("%w: %s", ErrUnSupportedProtocol, name)
21	}
22	func jsonObject(v any) (map[string]json.RawMessage, error) {
23		raw, err := json.Marshal(v)
24		if err != nil {
25			return nil, err
26		}
27		var object map[string]json.RawMessage
28		if err = json.Unmarshal(raw, &object); err != nil {
29			return nil, err
30		}
31		if object == nil {
32			object = map[string]json.RawMessage{}
33		}
34		return object, nil
35	}
36	func normalizeProtocol(fm fetcher.FetcherManager, v any) (any, error) {
37		raw, err := json.Marshal(v)
38		if err != nil {
39			return nil, err
40		}
41		target := fm.DefaultConfig()
42		if target == nil {
43			return nil, errors.New("protocol does not expose configuration")
44		}
45		// Managers may return either typed pointers or value/map defaults.
46		valueDefault := reflect.TypeOf(target).Kind() != reflect.Pointer
47		if valueDefault {
48			pointer := reflect.New(reflect.TypeOf(target))
49			defaults, err := json.Marshal(target)
50			if err != nil {
51				return nil, err
52			}
53			if err = json.Unmarshal(defaults, pointer.Interface()); err != nil {
54				return nil, err
55			}
56			target = pointer.Interface()
57		}
58		if err = json.Unmarshal(raw, target); err != nil {
59			return nil, err
60		}
61		if normalizer, ok := fm.(fetcher.ConfigNormalizer); ok {
62			raw, err = json.Marshal(target)
63			if err != nil {
64				return nil, err
65			}
66			return normalizer.NormalizeConfig(raw)
67		}
68		if valueDefault {
69			return reflect.ValueOf(target).Elem().Interface(), nil
70		}
71		return target, nil
72	}
73	
74	// preserveProtocolState ignores all client-supplied state, including null or
75	// malformed state values, before decoding/validating the writable config.
76	func preserveProtocolState(next, previous any) (any, error) {
77		object, err := jsonObject(next)
78		if err != nil {
79			return nil, err
80		}
81		before, err := jsonObject(previous)
82		if err != nil {
83			return nil, err
84		}
85		// Match encoding/json field folding as well as the canonical spelling.
86		for key := range object {
87			if strings.EqualFold(key, "state") {
88				delete(object, key)
89			}
90		}
91		if state, ok := before["state"]; ok {
92			object["state"] = state
93		}
94		return object, nil
95	}
96	func (d *Downloader) readProtocolConfig(name string) (any, error) {
97		if _, err := d.protocolManager(name); err != nil {
98			return nil, err
99		}
100		d.configLock.RLock()
101		defer d.configLock.RUnlock()
102		value := d.cfg.ProtocolConfig[name]
103		return *util.DeepClone(&value), nil
104	}
105	
106	// updateProtocolState is the only internal write path for backend-owned state.
107	// It never publishes callback edits outside the reserved state section.
108	func (d *Downloader) updateProtocolState(name string, change func(config, state json.RawMessage) (any, error)) error {
109		fm, err := d.protocolManager(name)
110		if err != nil {
111			return err
112		}
113		d.configLock.Lock()
114		defer d.configLock.Unlock()
115		if d.closed.Load() {
116			return errors.New("downloader is closed")
117		}
118		next := util.DeepClone(d.cfg.DownloaderStoreConfig)
119		object, err := jsonObject(next.ProtocolConfig[name])
120		if err != nil {
121			return err
122		}
123		state, ok := object["state"]
124		if !ok {
125			return fmt.Errorf("protocol %s does not expose persistent state", name)
126		}
127		raw, err := json.Marshal(object)
128		if err != nil {
129			return err
130		}
131		value, err := change(raw, state)
132		if err != nil {
133			return err
134		}
135		// Keep the transaction's original config isolated from callback mutations.
136		object["state"], err = json.Marshal(value)
137		if err != nil {
138			return err
139		}
140		normalized, err := normalizeProtocol(fm, object)
141		if err != nil {
142			return err
143		}
144		next.ProtocolConfig[name] = normalized
145		if err = d.storage.Put(bucketConfig, "config", next); err != nil {
146			return err
147		}
148		d.cfg.DownloaderStoreConfig.ProtocolConfig = next.ProtocolConfig
149		return nil
150	}
151	
152	// initProtocolConfigs loads the current schema and initializes missing defaults.
153	// This release intentionally does not import settings from older config layouts.
154	func (d *Downloader) initProtocolConfigs() error {
155		cfg := d.cfg.DownloaderStoreConfig
156		cfg.Init()
157		if err := cfg.GithubMirror.Validate(); err != nil {
158			return err
159		}
160		for _, fm := range d.cfg.FetchManagers {
161			value, ok := cfg.ProtocolConfig[fm.Name()]
162			if !ok {
163				value = map[string]any{}
164			}
165			normalized, err := normalizeProtocol(fm, value)
166			if err != nil {
167				return fmt.Errorf("%s config: %w", fm.Name(), err)
168			}
169			cfg.ProtocolConfig[fm.Name()] = normalized
170		}
171		return d.storage.Put(bucketConfig, "config", cfg)
172	}
