52	func (d *Downloader) InstallExtensionByFolder(path string, devMode bool) (*Extension, error) {
53		ext, err := d.parseExtensionByPath(path)
54		if err != nil {
55			return nil, err
56		}
57	
58		// if dev mode, don't copy to the extensions' directory
59		if devMode {
